// Recupera tutti gli elementi in ingresso dal Webhook
const items = $input.all();

const validatedItems = items.map(item => {

  // Estraiamo il body
  const data = item.json.body || {};

  let isValid = true;
  let errors = [];

  // 1. Controllo 'name' (obbligatorio)
  if (!data.name || String(data.name).trim() === '') {
    isValid = false;
    errors.push("Il campo 'name' è obbligatorio.");
  }

  // 2. Controllo 'email' (obbligatorio + formato valido)
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  if (!data.email || String(data.email).trim() === '') {
    isValid = false;
    errors.push("Il campo 'email' è obbligatorio.");
  } else if (!emailRegex.test(data.email)) {
    isValid = false;
    errors.push("Il formato della 'email' non è valido.");
  }

  // 3. Controllo 'company' (obbligatorio)
  if (!data.company || String(data.company).trim() === '') {
    isValid = false;
    errors.push("Il campo 'company' è obbligatorio.");
  }

  // 4. Controllo 'budget' (OPZIONALE)
  let budgetVal = data.budget;

  // Budget mancante = valido
  if (
    budgetVal === null ||
    budgetVal === undefined ||
    String(budgetVal).trim() === ""
  ) {

    // Normalizziamo il valore
    data.budget = null;

  } else {

    const budgetAsNumber = Number(budgetVal);

    // Budget presente: deve essere un numero >= 0
    if (isNaN(budgetAsNumber) || budgetAsNumber < 0) {

      isValid = false;

      errors.push(
        "Il campo 'budget' deve essere un numero maggiore o uguale a 0."
      );

    } else {

      // Convertiamo ad un vero numero
      data.budget = budgetAsNumber;
    }
  }

  // 5. Controllo 'message' (obbligatorio)
  if (!data.message || String(data.message).trim() === '') {
    isValid = false;
    errors.push("Il campo 'message' è obbligatorio.");
  }

  // Restituisce i dati puliti + risultato validazione
  return {
    json: {
      ...data,

      validation: {
        isValid: isValid,
        errors: errors
      }
    }
  };
});

return validatedItems;

const item = $input.first();

try {
  // Entriamo correttamente negli array usando [0] per 'output' e [0] per 'content'
  let rawText = item.json.output[0].content[0].text;

  // Rimuove i blocchi di formattazione Markdown se presenti (```json ... ```)
  if (rawText.includes('```json')) {
    rawText = rawText.split('```json')[1].split('```')[0];
  } else if (rawText.includes('```')) {
    rawText = rawText.split('```')[1].split('```')[0];
  }

  // Pulisce eventuali spazi vuoti o a capo rimasti
  rawText = rawText.trim();

  // Converte la stringa pulita in un vero oggetto JSON
  const parsedData = JSON.parse(rawText);

  // Forza 'business_needs' a essere un array di stringhe
  if (parsedData.business_needs && typeof parsedData.business_needs === 'string') {
    parsedData.business_needs = [parsedData.business_needs];
  } else if (!parsedData.business_needs) {
    parsedData.business_needs = [];
  }

  // Restituisce l'oggetto finale pulito
  return [{ json: parsedData }];

} catch (error) {
  // Se fallisce, ti mostra l'errore e dove si è piantato
  return [{ 
    json: { 
      error: "Impossibile decodificare il JSON dell'IA", 
      message: error.message
    } 
  }];
}

// Funzione per pulire la stringa del budget e convertirla in numero intero
function pulisciBudget(valore) {
  if (valore === null || valore === undefined || valore === 'unknown' || valore === '') {
    return null;
  }
  // Se è già un numero, lo restituisce direttamente
  if (typeof valore === 'number') return valore;

  // Rimuove € e spazi, poi toglie i punti usati come separatori delle migliaia
  let stringaPulita = valore.toString().replace(/[€\s]/g, '').replace(/\./g, '');
  let numero = parseInt(stringaPulita, 10);

  return isNaN(numero) ? null : numero;
}

// Cicla attraverso tutti i record in ingresso da n8n
for (const item of $input.all()) {
  let punteggio = 0;

  // 1. Calcolo punteggio Budget
  const budgetGrezzo = item.json.estimated_budget;
  const budget = pulisciBudget(budgetGrezzo);

  if (budget === null) {
    punteggio += 0;
  } else if (budget >= 5000) {
    punteggio += 40;
  } else if (budget >= 3000 && budget <= 4999) {
    punteggio += 30;
  } else if (budget >= 1000 && budget <= 2999) {
    punteggio += 20;
  } else if (budget < 1000) {
    punteggio += 10;
  }

  // 2. Calcolo punteggio Urgenza (gestisce italiano, inglese e formati misti)
  const urgenza = (item.json.urgency || '').toLowerCase().trim();
  if (urgenza === 'high' || urgenza === 'elevata' || urgenza === 'alto') {
    punteggio += 30;
  } else if (urgenza === 'medium' || urgenza === 'media' || urgenza === 'medio') {
    punteggio += 20;
  } else if (urgenza === 'low' || urgenza === 'bassa' || urgenza === 'basso') {
    punteggio += 10;
  } else {
    punteggio += 0; // Sconosciuta
  }

  // 3. Definizione della priorità in base al punteggio totale
  let priorita = 'BASSO';
  if (punteggio >= 60) {
    priorita = 'ALTO';
  } else if (punteggio >= 30 && punteggio <= 59) {
    priorita = 'MEDIO';
  }

  // Aggiunge i nuovi dati calcolati all'oggetto JSON originale
  item.json.punteggio_totale = punteggio;
  item.json.priorita_finale = priorita;
}

// Restituisce i dati pronti per il nodo successivo di n8n
return $input.all();

